style.css:
@-moz-document domain("chat.openai.com"), domain("chatgpt.com") {
body {
    background: #f6f8fa !important;
    color: #2e2e2e !important;
    font-family: "Courier New", monospace !important;
  }

  /* Центрируем чат */
  .flex.flex-col.items-center.text-sm {
    max-width: 800px !important;
    margin: 0 auto !important;
    padding: 1rem !important;
  }

  /* Удаляем боковое меню */
  nav, aside, .w-64, .md\\:w-64 {
    display: none !important;
  }

  /* Поле ввода */
  form, textarea, .absolute.bottom-0, .sticky.bottom-0 {
    width: 100% !important;
    max-width: 800px !important;
    margin: 0 auto !important;
    background: #ffffff !important;
    border-top: 1px solid #d0d7de !important;
    padding: 1rem !important;
    box-shadow: none !important;
  }

  textarea {
    background-color: #ffffff !important;
    color: #2e2e2e !important;
    border: 1px solid #d0d7de !important;
    border-radius: 6px !important;
    padding: 0.75rem !important;
    font-family: "Courier New", monospace !important;
    font-size: 14px !important;
  }

  /* Ответы в сером блоке */
  .markdown.prose, .whitespace-pre-wrap {
    background: #f0f0f0 !important;
    padding: 1rem !important;
    border-radius: 6px !important;
    margin: 1rem 0 !important;
    font-size: 14px !important;
    color: #2e2e2e !important;
  }

  /* Кнопки */
  button {
    background: #e6e6e6 !important;
    color: #000 !important;
    border: 1px solid #ccc !important;
    border-radius: 4px !important;
    font-family: inherit !important;
  }

  button:hover {
    background: #d0d0d0 !important;
  }

  /* Скрыть футер, подсказки и прочее */
  footer, .absolute.right-0, .sticky.top-0 {
    display: none !important;
  }
}
